# React Error Boundary Component

## Component Implementation

```tsx
// ErrorBoundary.tsx
import React, { Component, ErrorInfo, ReactNode } from "react";

// ─── Types ────────────────────────────────────────────────────────────────────

interface ErrorDetails {
  message: string;
  stack?: string;
  componentStack?: string;
  timestamp: string;
  errorId: string;
}

interface Props {
  children: ReactNode;
  /** Custom fallback UI – receives error details and a retry handler */
  fallback?: (props: FallbackProps) => ReactNode;
  /** Called whenever an error is caught */
  onError?: (details: ErrorDetails) => void;
  /** Reset the boundary when any of these values change */
  resetKeys?: unknown[];
}

interface State {
  hasError: boolean;
  errorDetails: ErrorDetails | null;
}

export interface FallbackProps {
  errorDetails: ErrorDetails;
  retry: () => void;
}

// ─── Helpers ──────────────────────────────────────────────────────────────────

function generateErrorId(): string {
  return `err_${Date.now()}_${Math.random().toString(36).slice(2, 9)}`;
}

function buildErrorDetails(
  error: Error,
  errorInfo: ErrorInfo
): ErrorDetails {
  return {
    message: error.message || "An unexpected error occurred",
    stack: error.stack,
    componentStack: errorInfo.componentStack ?? undefined,
    timestamp: new Date().toISOString(),
    errorId: generateErrorId(),
  };
}

function logError(details: ErrorDetails): void {
  const styles = {
    header: "color:#ff4d4f;font-size:14px;font-weight:bold",
    label: "color:#faad14;font-weight:bold",
    value: "color:#d9d9d9",
  };

  console.group("%c⛔ Error Boundary caught an error", styles.header);
  console.error("%cError ID:%c   " + details.errorId, styles.label, styles.value);
  console.error("%cTimestamp:%c  " + details.timestamp, styles.label, styles.value);
  console.error("%cMessage:%c    " + details.message, styles.label, styles.value);

  if (details.stack) {
    console.groupCollapsed("%cStack Trace", styles.label);
    console.error(details.stack);
    console.groupEnd();
  }

  if (details.componentStack) {
    console.groupCollapsed("%cComponent Stack", styles.label);
    console.error(details.componentStack);
    console.groupEnd();
  }

  console.groupEnd();
}

// ─── Default Fallback UI ──────────────────────────────────────────────────────

function DefaultFallback({ errorDetails, retry }: FallbackProps) {
  const [isExpanded, setIsExpanded] = React.useState(false);
  const [isCopied, setIsCopied] = React.useState(false);

  const handleCopy = async () => {
    const text = [
      `Error ID:   ${errorDetails.errorId}`,
      `Timestamp:  ${errorDetails.timestamp}`,
      `Message:    ${errorDetails.message}`,
      errorDetails.stack ? `\nStack:\n${errorDetails.stack}` : "",
      errorDetails.componentStack
        ? `\nComponent Stack:\n${errorDetails.componentStack}`
        : "",
    ]
      .filter(Boolean)
      .join("\n");

    await navigator.clipboard.writeText(text);
    setIsCopied(true);
    setTimeout(() => setIsCopied(false), 2000);
  };

  return (
    <div style={styles.overlay}>
      <div style={styles.card}>
        {/* Header */}
        <div style={styles.header}>
          <span style={styles.icon}>⚠️</span>
          <h2 style={styles.title}>Something went wrong</h2>
        </div>

        {/* Message */}
        <p style={styles.message}>{errorDetails.message}</p>

        {/* Meta */}
        <div style={styles.meta}>
          <span style={styles.metaItem}>
            🆔 <code style={styles.code}>{errorDetails.errorId}</code>
          </span>
          <span style={styles.metaItem}>
            🕐 {new Date(errorDetails.timestamp).toLocaleTimeString()}
          </span>
        </div>

        {/* Collapsible stack trace */}
        {(errorDetails.stack || errorDetails.componentStack) && (
          <div style={styles.detailsWrapper}>
            <button
              style={styles.toggleButton}
              onClick={() => setIsExpanded((v) => !v)}
            >
              {isExpanded ? "▲ Hide" : "▼ Show"} technical details
            </button>

            {isExpanded && (
              <pre style={styles.pre}>
                {[errorDetails.stack, errorDetails.componentStack]
                  .filter(Boolean)
                  .join("\n\n──────────────────\n\n")}
              </pre>
            )}
          </div>
        )}

        {/* Actions */}
        <div style={styles.actions}>
          <button style={styles.retryButton} onClick={retry}>
            🔄 Try Again
          </button>
          <button style={styles.copyButton} onClick={handleCopy}>
            {isCopied ? "✅ Copied!" : "📋 Copy Details"}
          </button>
          <button
            style={styles.reloadButton}
            onClick={() => window.location.reload()}
          >
            ↺ Reload Page
          </button>
        </div>
      </div>
    </div>
  );
}

// ─── Error Boundary Class ─────────────────────────────────────────────────────

export class ErrorBoundary extends Component<Props, State> {
  constructor(props: Props) {
    super(props);
    this.state = { hasError: false, errorDetails: null };
    this.retry = this.retry.bind(this);
  }

  // Derive state from the error synchronously before the next render
  static getDerivedStateFromError(error: Error): Partial<State> {
    return {
      hasError: true,
      // Full details are set in componentDidCatch (which has componentStack)
      errorDetails: {
        message: error.message || "An unexpected error occurred",
        stack: error.stack,
        componentStack: undefined,
        timestamp: new Date().toISOString(),
        errorId: generateErrorId(),
      },
    };
  }

  // Runs after render – receives the full ErrorInfo including componentStack
  componentDidCatch(error: Error, errorInfo: ErrorInfo): void {
    const errorDetails = buildErrorDetails(error, errorInfo);

    this.setState({ errorDetails });

    logError(errorDetails);
    this.props.onError?.(errorDetails);
  }

  // Reset when resetKeys change
  componentDidUpdate(prevProps: Props): void {
    const { resetKeys } = this.props;
    if (
      this.state.hasError &&
      resetKeys &&
      resetKeys.some((key, i) => key !== prevProps.resetKeys?.[i])
    ) {
      this.retry();
    }
  }

  retry(): void {
    this.setState({ hasError: false, errorDetails: null });
  }

  render(): ReactNode {
    const { hasError, errorDetails } = this.state;
    const { children, fallback } = this.props;

    if (hasError && errorDetails) {
      return fallback
        ? fallback({ errorDetails, retry: this.retry })
        : DefaultFallback({ errorDetails, retry: this.retry });
    }

    return children;
  }
}

// ─── Inline Styles ────────────────────────────────────────────────────────────
// Kept as a plain object so the component has zero external dependencies.

