    alignItems: "center",
    justifyContent: "center",
    minHeight: "100vh",
    padding: "24px",
    backgroundColor: "#0f0f0f",
    fontFamily: "'Segoe UI', system-ui, sans-serif",
  },
  card: {
    width: "100%",
    maxWidth: "600px",
    backgroundColor: "#1a1a1a",
    border: "1px solid #333",
    borderRadius: "12px",
    padding: "32px",
    boxShadow: "0 8px 32px rgba(0,0,0,0.5)",
  },
  header: {
    display: "flex",
    alignItems: "center",
    gap: "12px",
    marginBottom: "16px",
  },
  icon: { fontSize: "28px" },
  title: {
    margin: 0,
    fontSize: "22px",
    fontWeight: 700,
    color: "#ff4d4f",
  },
  message: {
    margin: "0 0 16px",
    color: "#d9d9d9",
    fontSize: "15px",
    lineHeight: 1.6,
  },
  meta: {
    display: "flex",
    flexWrap: "wrap",
    gap: "16px",
    marginBottom: "20px",
  },
  metaItem: { color: "#888", fontSize: "13px" },
  code: {
    fontFamily: "monospace",
    backgroundColor: "#2a2a2a",
    padding: "2px 6px",
    borderRadius: "4px",
    color: "#aaa",
    fontSize: "12px",
  },
  detailsWrapper: { marginBottom: "24px" },
  toggleButton: {
    background: "none",
    border: "1px solid #444",
    color: "#888",
    padding: "6px 12px",
    borderRadius: "6px",
    cursor: "pointer",
    fontSize: "13px",
