## Usage Examples

```tsx
// App.tsx

// 1. ─── Basic usage ───────────────────────────────────────────────────────────
function App() {
  return (
    <ErrorBoundary>
      <MyComponent />
    </ErrorBoundary>
  );
}

// 2. ─── With external error reporter ─────────────────────────────────────────
function App() {
  const handleError = (details: ErrorDetails) => {
    // Send to Sentry, Datadog, etc.
    fetch("/api/log-error", {
      method: "POST",
      body: JSON.stringify(details),
    });
  };

  return (
    <ErrorBoundary onError={handleError}>
      <MyComponent />
    </ErrorBoundary>
  );
}

// 3. ─── With resetKeys (auto-reset when route changes) ────────────────────────
function App() {
  const { pathname } = useLocation();

  return (
    <ErrorBoundary resetKeys={[pathname]}>
      <Routes />
    </ErrorBoundary>
  );
}

// 4. ─── With custom fallback UI ───────────────────────────────────────────────
function App() {
  return (
    <ErrorBoundary
      fallback={({ errorDetails, retry }) => (
        <div className="my-error-page">
          <h1>Oops! {errorDetails.message}</h1>
          <button onClick={retry}>Retry</button>
        </div>
      )}
    >
      <MyComponent />
    </ErrorBoundary>
  );
}

// 5. ─── Nested boundaries for partial recovery ────────────────────────────────
function Dashboard() {
  return (
    <ErrorBoundary> {/* catches whole dashboard */}
      <Sidebar />
      <ErrorBoundary> {/* isolates widget errors */}
        <WidgetGrid />
      </ErrorBoundary>
    </ErrorBoundary>
  );
}

// ─── Test component to trigger the boundary ───────────────────────────────────
function BombButton() {
  const [shouldThrow, setShouldThrow] = React.useState(false);
  if (shouldThrow) throw new Error("💣 Test explosion from BombButton!");
  return (
    <button onClick={() => setShouldThrow(true)}>
      Trigger Error Boundary
    </button>
  );
}
```

